"""Primes the regression head of LLMRegressionModel on the scores generated by the base LLM."""

import argparse
import json
import random
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable

import torch
import torch.nn.functional as F
from torch.optim import AdamW
from tqdm import tqdm
import wandb

from ita.base_score_model.data_utils import (
    load_argument_triples,
    load_raw_samples,
)
from ita.base_score_model.llm_regression_model import LLMRegressionModel


def analyst(
    statement, claim=None, support=False, topic=False, use_base_llm_prompt=False
) -> str:
    if not topic and claim is None:
        raise ValueError(
            "Claim is required for the analyst prompt without topic flag, but was None"
        )

    if topic:
        instructions = (
            "You are an analyst evaluating the validity of statements. "
            f'For the statement:\n\nStatement: "{statement}"\n\nplease give your confidence '
            f"that the statement is correct, accurate and truthful. "
            f"Your response should be between 0% and 100% with 0% indicating that the "
            f"considered statement is definitely invalid, 100% indicating that the considered statement is "
        )
    else:
        instructions = (
            "You are an analyst evaluating the validity and relevance of arguments. "
            f'For the argument:\n\nArgument: "{statement}"\n\nplease give your confidence '
            f"that the argument presents a compelling case {'in favour of' if support else 'against'} "
            f'the statement:\n\nStatement: "{claim}"\n\nYour assessment should be based '
            f"on how well the argument {'supports' if support else 'refutes'} the considered "
            "statement as well as the correctness, accuracy and truthfulness of the given argument. "
            f"Your response should be between 0% and 100% with 0% indicating that the "
            f"considered argument is definitely invalid, 100% indicating that the considered argument is "
        )

    if not use_base_llm_prompt:
        # Do not use the "Likelihood: " prefix when priming the regression head.
        return instructions + (
            "definitely valid and values in between indicating various levels of "
            "uncertainty. Your estimates should be well-calibrated, so feel free to "
            "err on the side of caution and output moderate probabilities if you are "
            "not completely sure in your assessment. "
            "Please respond in the following form:"
            "\n\n[The predicted likelihood that the considered "
            f"{'argument' if not topic else 'statement'} is valid as a number between 0 and 100]%"
            "\n\nReply only with the predicted likelihood without any additional text or explanation."
        )

    return instructions + (
        "definitely valid and values in between indicating various levels of "
        "uncertainty. Your estimates should be well-calibrated, so feel free to "
        "err on the side of caution and output moderate probabilities if you are "
        "not completely sure in your assessment. "
        "Please respond in the following form:"
        "\n\nLikelihood: The predicted likelihood that the considered "
        f"{'argument' if not topic else 'statement'} is valid"
    )


@dataclass
class PrimingSample:
    """A formatted conversation and its analyst-generated regression target."""

    conversation: list[dict[str, str]]
    target: float


def _unique_claims(data_path: str | Path) -> list[str]:
    """Return the ordered list of unique claims from a data file.

    Args:
        data_path (str | Path): Path to the JSON data file (either format).

    Returns:
        (list[str]): Unique claim strings in first-seen order.
    """
    seen: set[str] = set()
    claims: list[str] = []
    for sample in load_raw_samples(data_path):
        c = sample["claim"]
        if c not in seen:
            seen.add(c)
            claims.append(c)
    return claims


def _build_conversation(
    claim: str,
    argument: str | None = None,
    is_support: bool = False,
    topic: bool = False,
    use_base_llm_prompt: bool = False,
    print_prompt: bool = False,
) -> list[dict[str, str]]:
    """Construct the analyst user-turn conversation for a given sample.

    Args:
        claim (str): The claim being supported or attacked, or the statement
            to score when ``topic=True``.
        argument (str | None): The supporting or attacking argument.  Ignored
            when ``topic=True``.
        is_support (bool): Whether the argument supports (True) or attacks
            (False) the claim. Ignored when ``topic=True``.
        topic (bool): If True, build a topic-level prompt that scores the
            claim itself using ``analyst(..., topic=True)``.
        use_base_llm_prompt (bool): If True, use the base LLM prompt format with
            the "Likelihood: " prefix.
        print_prompt (bool): If True, print the generated prompt for debugging.
    """
    if topic:
        prompt_text = analyst(
            claim, topic=True, use_base_llm_prompt=use_base_llm_prompt
        )
    else:
        prompt_text = analyst(
            argument,
            claim=claim,
            support=is_support,
            use_base_llm_prompt=use_base_llm_prompt,
        )
    if print_prompt:
        print("Built Analyst prompt for generation:")
        print(prompt_text)
    return [{"role": "user", "content": prompt_text}]


def _parse_likelihood(text: str) -> float | None:
    """Extract a probability in [0, 1] from a 'Likelihood: X%' generation.

    Args:
        text (str): Raw text generated by the model.

    Returns:
        (float | None): Parsed probability, or None if the pattern is absent.
    """
    text = text.lower()
    text = text.replace("likelihood:", "").strip()
    text = text.replace("%", "").strip()
    text = text.split("\n")[0].strip()
    try:
        return int(text) / 100.0
    except ValueError:
        return None


def load_targets_from_scores(
    data_path: str | Path,
    include_claims: bool = False,
    seed: int = 42,
) -> list[PrimingSample]:
    """Load targets from a JSON file with pre-computed scores.

    Args:
        data_path (str | Path): Path to the JSON file with scores in the format
            {"claim": str, "support": list[str], "attack": list[str],
             "support_base_scores": list[float], "attack_base_scores": list[float],
             "claim_base_score": float}.
        include_claims (bool): If True, also include claim-level samples using
            "claim_base_score".
        seed (int): Random seed for shuffling.

    Returns:
        (list[PrimingSample]): Samples with conversations and float targets.
    """
    data_path = Path(data_path)
    data = json.loads(data_path.read_text())

    samples: list[PrimingSample] = []

    for item in data:
        claim = item["claim"]

        # Add support arguments
        for arg, score in zip(
            item["support"], item["support_base_scores"], strict=True
        ):
            conv = _build_conversation(claim, arg, is_support=True)
            samples.append(PrimingSample(conversation=conv, target=score))

        # Add attack arguments
        for arg, score in zip(item["attack"], item["attack_base_scores"], strict=True):
            conv = _build_conversation(claim, arg, is_support=False)
            samples.append(PrimingSample(conversation=conv, target=score))

        # Optionally add claim-level sample
        if include_claims:
            conv = _build_conversation(claim, topic=True)
            samples.append(
                PrimingSample(conversation=conv, target=item["claim_base_score"])
            )

    # Shuffle for consistency
    random.seed(seed)
    random.shuffle(samples)

    print(f"Loaded {len(samples)} samples from {data_path}")
    return samples


def generate_targets(
    model: LLMRegressionModel,
    triples: list[tuple[str, str, bool]],
    batch_size: int,
    cache_path: Path | None,
    claims: list[str] | None = None,
    seed: int = 42,
) -> list[PrimingSample]:
    """Generate analyst scores for all triples (and optionally claims) and pair
    them with conversations.

    If ``cache_path`` points to an existing file, targets are loaded from it
    and conversations are reconstructed deterministically — no generation is
    performed.  If the file does not exist, targets are generated and written
    to it.  The user is responsible for invalidating the cache when the
    ``analyst`` prompt template changes.

    The text fed to the generation pipeline is produced by
    ``tokenizer.apply_chat_template`` with ``add_generation_prompt=True`` and
    ``enable_thinking=False`` — identical to the text tokenized for the
    regression forward pass — ensuring hidden-state alignment between the
    target-generating context and the training context.

    Args:
        model (LLMRegressionModel): Model whose backbone and tokenizer are
            used for generation.
        triples (list[tuple[str, str, bool]]): (claim, argument, is_support)
            triples to generate argument-level scores for.
        batch_size (int): Number of prompts per generation call.
        cache_path (Path | None): Optional cache file.  Loaded if it exists;
            written after generation otherwise.
        claims (list[str] | None): If provided, also generate topic-level
            scores for these claim strings using ``analyst(..., topic=True)``.
        seed (int): Random seed to use for generation and sample shuffling.

    Returns:
        (list[PrimingSample]): Samples with conversations and float targets.
            Items for which the model produces an unparseable output are
            silently dropped.
    """
    # Load from cache if available
    if cache_path is not None and cache_path.exists():
        print(f"Loading targets from cache: {cache_path}")
        cached: dict[str, Any] = json.loads(cache_path.read_text())
        return [
            PrimingSample(
                conversation=_build_conversation(
                    item["claim"],
                    topic=True,
                )
                if item.get("is_topic", False)
                else _build_conversation(
                    item["claim"], item["argument"], item["is_support"]
                ),
                target=item["target"],
            )
            for item in cached["samples"]
        ]

    # Build all conversations to generate for
    # Argument-level conversations from triples.
    arg_conversations = [_build_conversation(c, a, s) for c, a, s in triples]
    # Topic-level conversations from claims (if requested).
    claim_conversations = (
        [_build_conversation(c, topic=True) for c in claims] if claims else []
    )
    all_conversations = arg_conversations + claim_conversations

    if not all_conversations:
        return []

    # Print sample prompts for debugging.
    if arg_conversations:
        _build_conversation(*triples[0], print_prompt=True)
    if claim_conversations:
        _build_conversation(claims[0], topic=True, print_prompt=True)  # type: ignore[index]

    # Generate targets in batches.
    raw_outputs = model.generate(
        input_conversations=all_conversations,
        batch_size=batch_size,
        seed=seed,
    )

    # Parse outputs, pairing only successfully parsed ones with conversations
    samples: list[PrimingSample] = []
    cache_items: list[dict[str, Any]] = []
    n_skipped = 0

    # Argument-level samples.
    for conv, (claim, arg, is_support), text in zip(
        arg_conversations, triples, raw_outputs[: len(triples)], strict=True
    ):
        target = _parse_likelihood(text)
        if target is None:
            n_skipped += 1
            print(
                f"Warning: Unparseable output for claim='{claim}', "
                f"argument='{arg}', is_support={is_support}: '{text}'"
            )
            continue
        samples.append(PrimingSample(conversation=conv, target=target))
        cache_items.append(
            {
                "claim": claim,
                "argument": arg,
                "is_support": is_support,
                "is_topic": False,
                "target": target,
            }
        )

    # Topic-level samples.
    # Slight duplicity in code structure, but the differences seem sufficiently
    # extensive to justify separation.
    for conv, claim, text in zip(
        claim_conversations,
        claims or [],
        raw_outputs[len(triples) :],
        strict=True,
    ):
        target = _parse_likelihood(text)
        if target is None:
            n_skipped += 1
            print(f"Warning: Unparseable topic output for claim='{claim}': '{text}'")
            continue
        samples.append(PrimingSample(conversation=conv, target=target))
        cache_items.append(
            {
                "claim": claim,
                "argument": None,
                "is_support": None,
                "is_topic": True,
                "target": target,
            }
        )

    if n_skipped:
        print(
            f"Warning: {n_skipped}/{len(all_conversations)} samples dropped "
            f"(unparseable output)."
        )

    # Consistently shuffle the samples and cache items.
    combined = list(zip(samples, cache_items))
    random.seed(seed)
    random.shuffle(combined)
    samples[:], cache_items[:] = zip(*combined)

    if cache_path is not None:
        cache_path.parent.mkdir(parents=True, exist_ok=True)
        cache_path.write_text(json.dumps({"samples": cache_items}, indent=2))
        print(f"Targets cached to {cache_path}")

    return samples


def train_epoch(
    model: LLMRegressionModel,
    samples: list[PrimingSample],
    optimizer: AdamW,
    batch_size: int,
    progress_log: Callable | None = None,
):
    """Run one training epoch, updating only the regression head.

    The backbone must already be frozen (all parameters set to
    ``requires_grad=False``) before calling this function.  With all backbone
    parameters frozen PyTorch does not build an autograd graph for the
    backbone forward pass, so no additional ``torch.no_grad()`` guard is
    needed around it.

    Args:
        model (LLMRegressionModel): Model with frozen backbone.
        samples (list[PrimingSample]): Training samples.
        optimizer (AdamW): Optimiser over ``model.regression_head.parameters()``.
        batch_size (int): Samples per gradient step.
    """
    model.backbone.eval()
    model.regression_head.train()

    total_loss = 0.0
    n_batches = 0
    for start in tqdm(range(0, len(samples), batch_size), desc="Training"):
        batch = samples[start : start + batch_size]
        targets = torch.tensor(
            [s.target for s in batch], dtype=torch.float32, device=model.input_device
        )
        preds = model.tokenize_forward([s.conversation for s in batch])
        loss = F.mse_loss(preds, targets)

        optimizer.zero_grad()
        loss.backward()
        optimizer.step()

        batch_loss = loss.item()
        if progress_log is not None:
            progress_log({"batch_loss": batch_loss})

        print(
            f"Batch {n_batches + 1}/{(len(samples) + batch_size - 1) // batch_size}: loss={batch_loss:.4f}"
        )

        total_loss += batch_loss
        n_batches += 1


def evaluate(
    model: LLMRegressionModel,
    samples: list[PrimingSample],
    batch_size: int,
) -> dict[str, float]:
    """Compute regression metrics over the full sample set.

    Args:
        model (LLMRegressionModel): Model to evaluate.
        samples (list[PrimingSample]): Evaluation samples.
        batch_size (int): Inference batch size.

    Returns:
        (dict[str, float]): ``{"eval/mse": float, "eval/mae": float,
            "eval/pearson_r": float}``.
    """
    model.eval()
    all_preds: list[float] = []
    all_targets: list[float] = []

    with torch.inference_mode():
        for start in tqdm(range(0, len(samples), batch_size), desc="Evaluating"):
            batch = samples[start : start + batch_size]
            preds = model.tokenize_forward([s.conversation for s in batch]).tolist()
            all_preds.extend(preds)
            all_targets.extend(s.target for s in batch)

    p = torch.tensor(all_preds)
    t = torch.tensor(all_targets)

    return {
        "mse": F.mse_loss(p, t).item(),
        "mae": (p - t).abs().mean().item(),
    }


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Prime the LLMRegressionModel head on analyst-generated scores."
    )
    parser.add_argument(
        "--data-path",
        default=None,
        help="Path to the JSON argument data file (required unless --scores-data-path is used).",
    )
    parser.add_argument("--model-name", default="Qwen/Qwen3-8B")
    parser.add_argument("--epochs", type=int, default=1)
    parser.add_argument(
        "--batch-size",
        type=int,
        default=8,
        help="Batch size for both generation and training.",
    )
    parser.add_argument("--lr", type=float, default=1e-4)
    parser.add_argument(
        "--output-dir", required=True, help="Directory for the saved checkpoint."
    )
    parser.add_argument(
        "--scores-data-path",
        default=None,
        help=(
            "Path to a JSON file with pre-computed scores. When provided, "
            "scores are loaded from this file instead of being generated. "
            "The --target-cache and --data-path arguments are ignored in this mode."
        ),
    )
    parser.add_argument(
        "--target-cache",
        default=None,
        help=(
            "JSON file for caching generated targets.  Loaded if it exists; "
            "written after generation otherwise.  The user is responsible for "
            "deleting this file when the analyst prompt changes."
        ),
    )
    parser.add_argument(
        "--include-claims",
        action="store_true",
        help=(
            "Also train the regression head on the claims themselves, using "
            "the analyst topic prompt (topic=True). Unique claims from "
            "--data-path are scored and added to the training set."
        ),
    )
    parser.add_argument(
        "--eval-data-paths",
        nargs="+",
        default=[],
        metavar="PATH",
        help=(
            "One or more additional data files to evaluate on after training. "
            "Each must be in one of the two supported formats. Results are "
            "reported separately for each dataset."
        ),
    )
    parser.add_argument(
        "--max-samples",
        type=int,
        default=None,
        help="Cap the number of training samples (useful for debugging).",
    )
    parser.add_argument(
        "--device-map",
        type=str,
        default="auto",
        help="Device map for model and tensors (e.g. 'auto', 'cuda:2').",
    )
    parser.add_argument(
        "--seed",
        type=int,
        default=42,
        help="Random seed for better reproducibility.",
    )
    parser.add_argument(
        "--wandb", action="store_true", help="Log metrics to Weights & Biases."
    )
    args = parser.parse_args()

    # Validate arguments
    if not args.scores_data_path and not args.data_path:
        parser.error("Either --data-path or --scores-data-path must be provided.")

    progress_log = None
    if args.wandb:
        wandb.init(project="argllms-priming-neo-gemma", config=vars(args))
        progress_log = wandb.log

    # Initialize model without LoRA (needed for both loading and generating)
    model = LLMRegressionModel(
        model_name=args.model_name,
        lora_config=None,
        device_map=args.device_map,
        seed=args.seed,
    )

    # Load or generate training targets
    if args.scores_data_path:
        # Load targets from a file with pre-computed scores
        print(f"Loading targets from scores file: {args.scores_data_path}")
        samples = load_targets_from_scores(
            args.scores_data_path,
            include_claims=args.include_claims,
            seed=args.seed,
        )
        print(f"Priming dataset: {len(samples)} samples.")
    else:
        # Load argument and claim samples
        triples = load_argument_triples(args.data_path)
        if args.max_samples is not None:
            triples = triples[: args.max_samples]
        print(f"Loaded {len(triples)} (claim, argument, is_support) triples.")

        claims: list[str] | None = None
        if args.include_claims:
            claims = _unique_claims(args.data_path)
            print(f"Including {len(claims)} unique claims for topic-level priming.")

        # Generate training targets or use cache if available
        cache_path = Path(args.target_cache) if args.target_cache else None
        samples = generate_targets(
            model,
            triples,
            batch_size=args.batch_size,
            cache_path=cache_path,
            claims=claims,
            seed=args.seed,
        )
        print(f"Priming dataset: {len(samples)} samples.")

    # Freeze backbone
    for p in model.backbone.parameters():
        p.requires_grad_(False)

    optimizer = AdamW(model.regression_head.parameters(), lr=args.lr)

    # Training loop
    for epoch in range(args.epochs):
        print(f"\n── Epoch {epoch + 1}/{args.epochs} ──")
        train_epoch(
            model,
            samples,
            optimizer,
            batch_size=args.batch_size,
            progress_log=progress_log,
        )
        eval_metrics = evaluate(model, samples, batch_size=args.batch_size)

        print()
        print("Evaluation metrics:")
        summary = "  ".join(f"{k}={v:.4f}" for k, v in eval_metrics.items())
        print(f"  {summary}")

        if progress_log is not None:
            progress_log({"epoch": epoch + 1, **eval_metrics})

    # Save checkpoint
    model.save_checkpoint(args.output_dir)
    print(f"\nCheckpoint saved to {args.output_dir}")

    # Evaluate on additional datasets
    if args.eval_data_paths:
        print("\n── Additional dataset evaluation ──")
        for i, eval_path in enumerate(args.eval_data_paths):
            print(f"\nEval dataset {i + 1}/{len(args.eval_data_paths)}: {eval_path}")
            eval_triples = load_argument_triples(eval_path)
            eval_claims: list[str] | None = (
                _unique_claims(eval_path) if args.include_claims else None
            )
            eval_samples = generate_targets(
                model,
                eval_triples,
                batch_size=args.batch_size,
                cache_path=None,
                claims=eval_claims,
            )
            print(f"  {len(eval_samples)} evaluation samples.")
            eval_metrics = evaluate(model, eval_samples, batch_size=args.batch_size)
            summary = "  ".join(f"{k}={v:.4f}" for k, v in eval_metrics.items())
            print(f"  {summary}")
            if progress_log is not None:
                progress_log({f"eval_ds{i}/{k}": v for k, v in eval_metrics.items()})

    if args.wandb:
        wandb.finish()


if __name__ == "__main__":
    main()
